<?php
namespace App\Http\Requests\ProfileUpdates;
use App\Models\ProfileUpdateRequestChange;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Validator;
class StoreProfileUpdateRequest extends FormRequest{public function authorize():bool{return true;}public function rules():array{return ['changes'=>['required','array','min:1','max:20'],'club_id'=>['prohibited'],'member_id'=>['prohibited'],'requester_user_id'=>['prohibited'],'reviewer_user_id'=>['prohibited'],'status'=>['prohibited'],'lock_version'=>['prohibited']];}public function after():array{return[function(Validator $v):void{$unknown=array_diff(array_keys($this->all()),array_keys($this->rules()));if($unknown)$v->errors()->add('payload','Unknown fields: '.implode(', ',$unknown));$changes=$this->input('changes',[]);if(is_array($changes)){if(array_is_list($changes))$v->errors()->add('changes','Changes must be keyed by field name.');$bad=array_diff(array_keys($changes),ProfileUpdateRequestChange::ALLOWED_FIELDS);if($bad)$v->errors()->add('changes','Unsupported fields: '.implode(', ',$bad));}}];}}
